     and has_function_privilege('authenticated', 'public.studio_cost_breakdown(date,date)', 'execute')
     and not has_function_privilege('anon', 'public.event_cost_breakdown(uuid)', 'execute')
     and not has_function_privilege('anon', 'public.studio_cost_breakdown(date,date)', 'execute')
     and position('has_area(''finance''' in (select prosrc from pg_proc where oid = to_regprocedure('public.event_cost_breakdown(uuid)'))) > 0
     and position('has_area(''business''' in (select prosrc from pg_proc where oid = to_regprocedure('public.studio_cost_breakdown(date,date)'))) > 0),
  ('05 internal helpers are not callable by the app',
     not has_function_privilege('authenticated', 'public._r21_event_money(uuid,uuid,boolean)', 'execute')
     and not has_function_privilege('authenticated', 'public._r21_cost_lines(uuid,uuid)', 'execute')
     and not has_function_privilege('authenticated', 'public._vb_event_pnl(uuid,uuid)', 'execute')
     and not has_function_privilege('authenticated', 'public._vb_event_pnl__pre0246(uuid,uuid)', 'execute')
     and not has_function_privilege('anon', 'public._r21_event_money(uuid,uuid,boolean)', 'execute')),
  ('06 event_pnl unchanged (finance check, signed-in only)',
     position('has_area(''finance''' in (select prosrc from pg_proc where oid = to_regprocedure('public.event_pnl(uuid)'))) > 0
     and has_function_privilege('authenticated', 'public.event_pnl(uuid)', 'execute')
     and not has_function_privilege('anon', 'public.event_pnl(uuid)', 'execute')),
  ('07 the marker table is closed to the app',
     not has_table_privilege('authenticated', 'public.helm_money_rules', 'select')
     and not has_table_privilege('anon', 'public.helm_money_rules', 'select')),
  ('08 insights_event_costs reads the ledger (crew wages counted), insights + finance, signed-in only',
     position('r21-money-0246' in (select prosrc from pg_proc where oid = to_regprocedure('public.insights_event_costs(date,date)'))) > 0
     and position('has_area(''insights''' in (select prosrc from pg_proc where oid = to_regprocedure('public.insights_event_costs(date,date)'))) > 0
     and has_function_privilege('authenticated', 'public.insights_event_costs(date,date)', 'execute')
     and not has_function_privilege('anon', 'public.insights_event_costs(date,date)', 'execute'))
) v(item, ok)
union all
